# ---------------------------------------------------------
# SVG 小工具（统一 viewBox=0 0 320 H，手机端自适应宽度）
# ---------------------------------------------------------

def timeline(items, h=118, color="#a9683c"):
    """
    横向时间轴。
    items: [(年份文字, 事件文字), ...]  建议 3~5 项
    """
    n = len(items)
    if n == 0:
        return ""
    gap = 320 / (n + 1)
    out = [f'<svg viewBox="0 0 320 {h}" xmlns="http://www.w3.org/2000/svg" '
           f'style="width:100%;height:auto;display:block">']
    # 主轴
    out.append(f'<line x1="16" y1="52" x2="304" y2="52" stroke="{color}" '
               f'stroke-width="2.5" stroke-linecap="round"/>')
    # 右端箭头
    out.append(f'<path d="M304 52 l-9 -5 l0 10 z" fill="{color}"/>')
    for i, (yr, ev) in enumerate(items):
        x = gap * (i + 1)
        y = 52
        out.append(f'<circle cx="{x:.1f}" cy="{y}" r="5" fill="#fff" '
                   f'stroke="{color}" stroke-width="2.5"/>')
        out.append(f'<text x="{x:.1f}" y="{y-13}" font-size="11" font-weight="700" '
                   f'fill="{color}" text-anchor="middle">{yr}</text>')
        # 事件文字：太长的拆两行
        ev_s = ev
        if len(ev_s) > 7:
            a, b = ev_s[:7], ev_s[7:14]
            out.append(f'<text x="{x:.1f}" y="{y+18}" font-size="9.5" '
                       f'fill="#6b6357" text-anchor="middle">{a}</text>')
            out.append(f'<text x="{x:.1f}" y="{y+30}" font-size="9.5" '
                       f'fill="#6b6357" text-anchor="middle">{b}</text>')
        else:
            out.append(f'<text x="{x:.1f}" y="{y+19}" font-size="9.5" '
                       f'fill="#6b6357" text-anchor="middle">{ev_s}</text>')
    out.append('</svg>')
    return "".join(out)


def flow(steps, color="#a9683c", h=None):
    """竖向流程/递进示意（步骤 3~4 个）"""
    n = len(steps)
    step_h = 34
    total = h or (n * step_h + 14)
    out = [f'<svg viewBox="0 0 320 {total}" xmlns="http://www.w3.org/2000/svg" '
           f'style="width:100%;height:auto;display:block">']
    for i, s in enumerate(steps):
        y = 10 + i * step_h
        out.append(f'<rect x="18" y="{y}" width="284" height="26" rx="7" '
                   f'fill="#fbf6ef" stroke="{color}" stroke-width="1.2"/>')
        out.append(f'<text x="30" y="{y+18}" font-size="11.5" fill="#4a4238">{s}</text>')
        if i < n - 1:
            out.append(f'<path d="M160 {y+26} l0 6 m-4 -3 l4 3 l4 -3" '
                       f'stroke="{color}" stroke-width="1.6" fill="none"/>')
    out.append('</svg>')
    return "".join(out)


def map_dots(points, color="#a9683c", note="", h=180):
    """
    极简"分布示意"图：用圆点标注若干要素的相对位置。
    points: [(名称, x%, y%), ...]
    """
    out = [f'<svg viewBox="0 0 320 {h}" xmlns="http://www.w3.org/2000/svg" '
           f'style="width:100%;height:auto;display:block">']
    out.append(f'<rect x="10" y="10" width="300" height="{h-20}" rx="10" '
               f'fill="#faf7f2" stroke="#e3dbcf" stroke-width="1"/>')
    for name, px, py in points:
        x = 10 + 300 * px / 100
        y = 10 + (h - 20) * py / 100
        out.append(f'<circle cx="{x:.0f}" cy="{y:.0f}" r="4.5" fill="{color}"/>')
        out.append(f'<text x="{x:.0f}" y="{y-8:.0f}" font-size="9.5" '
                   f'fill="#5a5147" text-anchor="middle">{name}</text>')
    if note:
        out.append(f'<text x="160" y="{h-6}" font-size="9" fill="#9a9086" '
                   f'text-anchor="middle">{note}</text>')
    out.append('</svg>')
    return "".join(out)


