    {"q": "秦朝为抵御北方匈奴修筑的工程是（　）", "o": ["大运河", "长城", "都江堰", "灵渠"], "a": 1, "e": "秦朝修筑长城抵御匈奴，同时开凿灵渠沟通南北。"}
