    {"q": "关于皇帝制度的理解，正确的是（　）", "o": ["皇帝权力受丞相制约", "皇帝独揽大权、皇权至上", "皇帝由贵族推举产生", "皇帝权力受法律严格限制"], "a": 1, "e": "皇帝制度的核心是皇权至上、皇位世袭。"},
