    {"q": "郡县制取代分封制，从本质上反映了（　）", "o": ["地方权力的扩大", "贵族政治的终结与官僚政治的确立", "中央权力的削弱", "军事制度的变革"], "a": 1, "e": "郡县制使官吏由中央任免，是官僚政治取代贵族政治的标志。"},
