    {"q": "唐朝制度创新的历史意义在于（　）", "o": ["彻底废除了旧制度", "为后世政治与赋税制度提供了重要借鉴", "结束了封建制度", "实现了君主立宪"], "a": 1, "e": "隋唐制度创新为后世提供了重要借鉴，影响深远。"},
