    {"q": "\"诗圣\"指的是（　）", "o": ["李白", "杜甫", "白居易", "王维"], "a": 1, "e": "杜甫被称为\"诗圣\"，其诗反映现实，被称为\"诗史\"。"},
    {"q": "\"诗仙\"指的是（　）", "o": ["李白", "杜甫", "白居易", "李商隐"], "a": 0, "e": "李白被称为\"诗仙\"，诗风豪放浪漫。"},
    {"q": "被称为\"书圣\"的是（　）", "o": ["颜真卿", "柳公权", "王羲之", "张旭"], "a": 2, "e": "东晋王羲之被称为\"书圣\"，代表作《兰亭序》。"},
