    {"q": "《大唐西域记》的作者是（　）", "o": ["法显", "玄奘", "鉴真", "玄奘弟子"], "a": 1, "e": "玄奘口述、弟子记录成《大唐西域记》。"},
    {"q": "唐朝反对佛道、提倡复兴儒学的是（　）", "o": ["韩愈", "柳宗元", "范缜", "董仲舒"], "a": 0, "e": "韩愈提出复兴儒学，反对佛道思想。"},
    {"q": "隋唐时期在东亚文化圈中的地位是（　）", "o": ["边缘地区", "文化中心", "受外来文化主导", "与外界隔绝"], "a": 1, "e": "隋唐时期中国是东亚文化圈的中心，日本、朝鲜纷纷来华学习。"}
