    {"q": "唐朝统治者奉行三教并行政策的主要目的是（　）", "o": ["放弃儒学", "维护统治、调和思想矛盾", "发展经济", "加强军事"], "a": 1, "e": "三教并行有利于调和思想矛盾，维护统治。"},
