    {"q": "元朝与唐宋相比，边疆管理的特点是（　）", "o": ["更加松散", "更加有效", "完全放弃", "只有形式"], "a": 1, "e": "元朝在西藏、云南等地设机构管辖，边疆管理更加有效。"}
