    {"q": "黄宗羲\"工商皆本\"主张的意义是（　）", "o": ["彻底否定重农抑商", "反映了商品经济发展的要求", "主张闭关锁国", "维护自然经济"], "a": 1, "e": "\"工商皆本\"反映了商品经济发展的时代要求。"},
    {"q": "明清时期\"重农抑商\"政策与\"闭关锁国\"政策的共同作用是（　）", "o": ["促进了经济发展", "阻碍了商品经济发展和社会进步", "加强了对外交流", "推动了科技发展"], "a": 1, "e": "两者都阻碍了商品经济发展和社会进步。"},
    {"q": "明清科技成就的特点不包括（　）", "o": ["总结性著作多", "传统科技继续发展", "开始吸收西方科技", "全面超越西方"], "a": 3, "e": "明清科技虽有总结性成就，但已逐渐落后于西方。"},
    {"q": "明末清初思想活跃局面出现的根本原因是（　）", "o": ["统治者提倡", "商品经济发展与封建制度衰落", "外来思想传入", "科举制发展"], "a": 1, "e": "商品经济发展与封建制度衰落是思想活跃的根本原因。"},
    {"q": "徐光启《农政全书》的特点之一是（　）", "o": ["完全排斥西方科技", "吸收西方农业科技知识", "只讲传统农业", "否定农业重要性"], "a": 1, "e": "《农政全书》吸收西方农业科技，体现开放态度。"},
